180	/// One length's runs: each run's mean sample time at it, ns, and the fold the run is in.
181	#[derive(Debug, Clone)]
182	struct Point {
183	    length: u64,
184	    runs: Vec<(f64, usize)>,
185	}
186	
187	impl Point {
188	    /// Every run's value.
189	    fn values(&self) -> Vec<f64> {
190	        self.runs.iter().map(|r| r.0).collect()
191	    }
192	
193	    /// The length's level over its runs: the trimmed mean, how many runs it kept, and its
194	    /// standard error, or the plain mean and its own where the runs are too few to trim.
195	    fn level(&self, trim: Trim) -> (f64, usize, f64) {
196	        let values = self.values();
197	        match Trimmed::of(&values, trim) {
198	            Some(t) => (t.mean, t.kept() as usize, t.se()),
199	            None => {
200	                let se = match stdev(&values) {
201	                    Some(sd) => sd / (values.len() as f64).sqrt(),
202	                    None => 0.0,
203	                };
204	                (mean(&values), values.len(), se)
205	            }
206	        }
207	    }
208	
209	    /// The plain mean over the runs in `fold`, `None` when it has none.
210	    fn fold_mean(&self, fold: usize) -> Option<f64> {
211	        let values: Vec<f64> = self
212	            .runs
213	            .iter()
214	            .filter(|r| r.1 == fold)
215	            .map(|r| r.0)
216	            .collect();
217	        (!values.is_empty()).then(|| mean(&values))
218	    }
219	}
220	
221	/// What a group is of: a bench at a host and a placement, over fixed counts or one span.
222	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
223	struct GroupKey {
224	    bench: String,
225	    host: String,
226	    placement: String,
227	    /// The span its runs drew from, `None` for runs at fixed counts.
228	    span: Option<(u64, u64)>,
229	}
230	
231	/// A group's runs gathered by length.
232	#[derive(Debug, Clone)]
233	struct Group {
234	    key: GroupKey,
235	    points: Vec<Point>,
236	    n_runs: usize,
237	    /// Each fixed run's standard error of its own sample time, from its blocks, ns.
238	    block_se: Vec<f64>,
239	    /// Each spanned run's own slope, ns a step.
240	    run_slopes: Vec<f64>,
241	}
242	
243	/// The fold of each run: by its `pass` tag where the runs carry one, the first value against
244	/// the rest, and by the run number's parity where they do not.
245	fn folds(runs: &[&RegressionRun]) -> Vec<usize> {
246	    let mut passes: Vec<&str> = runs
247	        .iter()
248	        .filter_map(|r| r.tags.get("pass").map(String::as_str))
249	        .collect();
250	    passes.sort_unstable();
251	    passes.dedup();
252	    runs.iter()
253	        .map(|r| match r.tags.get("pass") {
254	            Some(p) if passes.len() > 1 => usize::from(p.as_str() != passes[0]),
255	            _ => (r.run % 2) as usize,
256	        })
257	        .collect()
258	}
259	
260	/// Gather `runs` into groups, each group's points in length order.
261	fn groups(runs: &[RegressionRun]) -> Vec<Group> {
262	    let mut by_key: BTreeMap<GroupKey, Vec<&RegressionRun>> = BTreeMap::new();
263	    for run in runs {
264	        let span = (run.inner_lo != run.inner_hi).then_some((run.inner_lo, run.inner_hi));
265	        by_key
266	            .entry(GroupKey {
267	                bench: run.bench.clone(),
268	                host: run.host.clone(),
269	                placement: run.placement.clone(),
270	                span,
271	            })
272	            .or_default()
273	            .push(run);
274	    }
275	    by_key
276	        .into_iter()
277	        .map(|(key, runs)| {
278	            let fold = folds(&runs);
279	            let mut by_length: BTreeMap<u64, Vec<(f64, usize)>> = BTreeMap::new();
280	            let mut block_se = Vec::new();
281	            let mut run_slopes = Vec::new();
282	            for (run, &fold) in runs.iter().zip(&fold) {
283	                if key.span.is_none() {
