534	/// Fit `group` under `trim`, `None` when it has under [`MIN_LENGTHS`] lengths.
535	fn fit(group: &Group, trim: Trim) -> Option<Fitted> {
536	    if group.points.len() < MIN_LENGTHS {
537	        return None;
538	    }
539	    let levels: Vec<(f64, usize, f64)> = group.points.iter().map(|p| p.level(trim)).collect();
540	    let points: Vec<(f64, f64)> = group
541	        .points
542	        .iter()
543	        .zip(&levels)
544	        .map(|(p, l)| (p.length as f64, l.0))
545	        .collect();
546	    let se: Vec<f64> = levels.iter().map(|l| l.2).collect();
547	    let line = ols(&points)?;
548	    let res = residuals(&line, &points);
549	    let plain_points: Vec<(f64, f64)> = group
550	        .points
551	        .iter()
552	        .map(|p| (p.length as f64, mean(&p.values())))
553	        .collect();
554	    let halves = halves(&points, &se, &line);
555	    let lengths: Vec<u64> = group.points.iter().map(|p| p.length).collect();
556	    let fold =
557	        |f: usize| -> Option<Vec<f64>> { group.points.iter().map(|p| p.fold_mean(f)).collect() };
558	    let period = match (fold(0), fold(1)) {
559	        (Some(a), Some(b)) => period(&lengths, &a, &b),
560	        _ if lengths.windows(2).any(|w| w[1] != w[0] + 1) => Period::NotConsecutive,
561	        _ => Period::NoFolds,
562	    };
563	    let consecutive = period != Period::NotConsecutive;
564	    let run_sds: Vec<f64> = group
565	        .points
566	        .iter()
567	        .filter_map(|p| stdev(&p.values()))
568	        .collect();
569	    let run_slopes = median(&group.run_slopes).map(|mid| {
570	        let strays = group
571	            .run_slopes
572	            .iter()
573	            .filter(|s| (*s - mid).abs() * 100.0 / mid.abs() > STRAY_PCT)
574	            .count();
575	        let lo = group
576	            .run_slopes
577	            .iter()
578	            .copied()
579	            .fold(f64::INFINITY, f64::min);
580	        let hi = group
581	            .run_slopes
582	            .iter()
583	            .copied()
584	            .fold(f64::NEG_INFINITY, f64::max);
585	        (lo, hi, strays, group.run_slopes.len())
586	    });
587	    Some(Fitted {
588	        line,
589	        errors: standard_errors(&points, &res),
590	        plain: ols(&plain_points),
591	        run_sd: median(&run_sds),
592	        block_se: median(&group.block_se),
593	        verdict: verdict(halves.as_ref()),
594	        halves,
595	        period,
596	        lag1: if consecutive { lag1(&res) } else { None },
597	        run_slopes,
598	        rows: group
599	            .points
600	            .iter()
601	            .zip(&levels)
602	            .map(|(p, l)| Row {
603	                length: p.length,
604	                kept: l.1,
605	                of: p.runs.len(),
606	                sample_ns: l.0,
607	                line_ns: line.at(p.length as f64),
608	            })
609	            .collect(),
610	    })
611	}
