846	/// The `linear-regression` command, `lr` for short: read `paths`, group the runs by bench, host,
847	/// placement, and how they took their lengths, and print each group's regression under `trim`.
848	/// Returns the exit code.
849	pub fn run(paths: &[PathBuf], trim: Trim) -> i32 {
850	    if paths.is_empty() {
851	        eprintln!("error: linear-regression: name the record files or directories to read");
852	        return 2;
853	    }
854	    let files = match crate::analyze::record_files(paths) {
855	        Ok(files) => files,
856	        Err(e) => {
857	            eprintln!("error: linear-regression: {e}");
858	            return 1;
859	        }
860	    };
861	    let mut skipped = Skipped::default();
862	    let mut runs = Vec::new();
863	    for file in &files {
864	        match record::read_regression(file, &mut skipped) {
865	            Ok(read) => runs.extend(read),
866	            Err(e) => {
867	                eprintln!("error: linear-regression: {e}");
868	                return 1;
869	            }
870	        }
871	    }
872	    let groups = groups(&runs);
873	    let fitted: Vec<(&Group, Fitted)> = groups
874	        .iter()
875	        .filter_map(|g| fit(g, trim).map(|f| (g, f)))
876	        .collect();
877	    println!(
878	        "{} runs in {} file{}, {} groups fitted, trim {trim}",
879	        runs.len(),
880	        files.len(),
881	        if files.len() == 1 { "" } else { "s" },
882	        fitted.len()
883	    );
884	    if skipped.unreadable > 0 {
885	        println!("skipped: {} unreadable lines", skipped.unreadable);
886	    }
887	    let unfitted = groups.len() - fitted.len();
888	    if unfitted > 0 {
889	        println!(
890	            "not fitted: {unfitted} group{} with under {MIN_LENGTHS} values of inner",
891	            if unfitted == 1 { "" } else { "s" }
892	        );
893	    }
894	    if fitted.is_empty() {
895	        return 0;
896	    }
897	    println!("\n{LEGEND}");
898	    for (group, f) in &fitted {
899	        println!("{}", report(group, f));
900	    }
901	    0
902	}
