323	/// Whether a line describes a group, from the slopes of its two halves.
324	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
325	enum Verdict {
326	    /// The halves' slopes agree: the slope is a step's cost.
327	    Holds,
328	    /// They differ by more than the runs' scatter allows: no cost is named.
329	    Fails,
330	    /// The runs' scatter is wider than the agreement asked for and than the difference seen, so
331	    /// the halves can neither hold the line nor refuse it.
332	    Noisy,
333	    /// Too few lengths for two halves.
334	    Untested,
335	}
336	
337	/// The line through each half of the lengths, and how far apart their slopes are.
338	#[derive(Debug, Clone, Copy)]
339	struct Halves {
340	    lower: Line,
341	    upper: Line,
