struct Overhead {
    ns: f64,
    from: String,
}

/// The overhead `group` is read against: `given` where the command line names one, and
/// otherwise the intercept of a [`CALIBRATION`] group on the same host whose lengths were
/// taken the same way and whose line holds. Of several, one at the group's own placement is
/// taken first, and then the one whose intercept is the best determined.
fn overhead_for(
    group: &Group,
    fitted: &[(&Group, Fitted)],
    given: Option<f64>,
) -> Option<Overhead> {
    if let Some(ns) = given {
        return Some(Overhead {
            ns,
            from: "--overhead".to_string(),
        });
    }
    let rank = |(g, f): &(&Group, Fitted)| {
        (
            g.key.placement != group.key.placement,
            f.errors.map_or(f64::INFINITY, |e| e.2),
        )
    };
    fitted
        .iter()
        .filter(|(g, f)| {
            g.key.bench == CALIBRATION
                && g.key.host == group.key.host
                && g.key.span.is_some() == group.key.span.is_some()
                && f.verdict == Verdict::Holds
        })
        .min_by(|a, b| {
            let (a, b) = (rank(a), rank(b));
            a.0.cmp(&b.0).then(a.1.total_cmp(&b.1))
        })
        .map(|(g, f)| Overhead {
            ns: f.line.intercept,
            from: if g.key == group.key {
                "this group's own intercept".to_string()
            } else {
                format!("{} {}, {}", g.key.bench, g.key.placement, how(g))
